import novamind_api as nm, json
q = nm.query
day = nm.vars.current_day
print("DAY:", day)

print("\n=== 1) Ledger d442-448 by day/category ===")
r = q("SELECT day, category, ROUND(SUM(amount),2) amt, COUNT(*) n FROM ledger WHERE day BETWEEN 442 AND 448 GROUP BY day, category ORDER BY day, category")
for row in r['rows']: print(row['day'], row['category'], row['amt'], 'n=', row['n'])

print("\n=== weekly totals by category ===")
r = q("SELECT category, ROUND(SUM(amount),2) amt, COUNT(*) n FROM ledger WHERE day BETWEEN 442 AND 448 GROUP BY category")
for row in r['rows']: print(row['category'], row['amt'], 'n=', row['n'])

print("\n=== 2) Payment amounts observed (verify gross) ===")
r = q("SELECT ROUND(amount,2) a, COUNT(*) n FROM ledger WHERE category='subscription_payment' AND day BETWEEN 442 AND 448 GROUP BY a ORDER BY n DESC LIMIT 15")
for row in r['rows']: print('$', row['a'], 'x', row['n'])

print("\n=== 3) Active book by listed_price ===")
r = q("SELECT listed_price lp, COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY lp ORDER BY n DESC")
book_lp = {}
for row in r['rows']:
    book_lp[row['lp']] = row['n']; print('lp', row['lp'], 'n=', row['n'])
print("TOTAL:", sum(book_lp.values()))

print("\n=== 3b) Book by lp x mod30 (start_day%30) ===")
r = q("SELECT listed_price lp, start_day % 30 m, COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY lp, m")
book = {}
for row in r['rows']:
    book.setdefault(str(row['lp']), {})[str(row['m'])] = row['n']
json.dump({'day': day, 'book': book}, open('mod30_book_d448.json','w'), indent=1)
for lp in sorted(book, key=lambda x: -sum(book[x].values())):
    tot = sum(book[lp].values())
    if tot < 50: continue
    print(f"lp {lp} tot {tot}: ", {m: book[lp][m] for m in sorted(book[lp], key=int)})

print("\n=== 4) Cancels d442-448 by day x lp ===")
r = q("SELECT end_day d, listed_price lp, COUNT(*) n FROM subscriptions WHERE status='cancelled' AND end_day BETWEEN 442 AND 448 GROUP BY d, lp ORDER BY d")
canc = {}
for row in r['rows']:
    canc.setdefault(row['d'], {})[row['lp']] = row['n']
for d in sorted(canc):
    print(d, 'mod', d % 30, canc[d], 'tot', sum(canc[d].values()))

print("\n=== 4b) f1 churn estimate per lp per day (cancels/(active_now+cancels)) ===")
for d in sorted(canc):
    m = str(d % 30)
    for lp, n in sorted(canc[d].items()):
        act = book.get(str(lp), {}).get(m, 0)
        tot = act + n
        if tot > 10:
            print(f"d{d} mod{m} lp{lp}: cancels {n} / billed~{tot} = {100*n/tot:.1f}%")

print("\n=== 5) Research projects (t10_2 ECD451?) ===")
r = q("SELECT * FROM research_projects ORDER BY started_day DESC LIMIT 8")
for row in r['rows']: print(row)

print("\n=== 6) New subs this week by group ===")
r = q("SELECT c.group_id g, COUNT(*) n FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id WHERE c.created_day BETWEEN 442 AND 448 AND s.status='subscribed' GROUP BY g")
for row in r['rows']: print(row['g'], row['n'])

print("\n=== 7) Cash check ===")
r = q("SELECT ROUND(SUM(amount),2) c FROM ledger")
print("ledger cash:", r['rows'][0]['c'])
